package dev.veltraph.client.rewarp.mc;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class IssuedReturnSelectedSetterJournalTest {
 @Test void ordinarySnapshotRefusesSameSlotSetter(){var s=IssuedReturnMutationJournal.open();try{var i=new Object();assertTrue(s.watch(i));IssuedReturnMutationJournal.selectedSlotMutation(i,2);assertFalse(s.current());}finally{s.close();}}
 @Test void exactOneSetterNormalReturnPreservesOnlyItsSnapshot(){var a=IssuedReturnMutationJournal.open();var b=IssuedReturnMutationJournal.open();try{var i=new Object();a.watch(i);b.watch(i);var w=a.beginNativeSelectedSetter(i,2);assertNotNull(w);assertFalse(a.current());IssuedReturnMutationJournal.selectedSlotMutation(i,2);assertFalse(a.current());assertTrue(a.finishNativeSelectedSetter(w,true));assertTrue(a.current());assertFalse(b.current());}finally{a.close();b.close();}}
 @Test void secondSameSlotSetterRefusesPermanently(){var s=IssuedReturnMutationJournal.open();try{var i=new Object();s.watch(i);var w=s.beginNativeSelectedSetter(i,2);IssuedReturnMutationJournal.selectedSlotMutation(i,2);IssuedReturnMutationJournal.selectedSlotMutation(i,2);assertFalse(s.finishNativeSelectedSetter(w,true));assertNull(s.beginNativeSelectedSetter(i,2));}finally{s.close();}}
 @Test void wrongRequestedSlotRefuses(){var s=IssuedReturnMutationJournal.open();try{var i=new Object();s.watch(i);var w=s.beginNativeSelectedSetter(i,2);IssuedReturnMutationJournal.selectedSlotMutation(i,3);assertFalse(s.finishNativeSelectedSetter(w,true));}finally{s.close();}}
 @Test void absentNativeHeadCannotInventSuccess(){var s=IssuedReturnMutationJournal.open();try{var i=new Object();s.watch(i);var w=s.beginNativeSelectedSetter(i,2);assertFalse(s.finishNativeSelectedSetter(w,true));}finally{s.close();}}
 @Test void thrownSetterRevokesEvenAfterItsHead(){var s=IssuedReturnMutationJournal.open();try{var i=new Object();s.watch(i);var w=s.beginNativeSelectedSetter(i,2);IssuedReturnMutationJournal.selectedSlotMutation(i,2);assertFalse(s.finishNativeSelectedSetter(w,false));}finally{s.close();}}
 @Test void contentMutationCannotBeBorrowedAsSelectedSetter(){var s=IssuedReturnMutationJournal.open();try{var i=new Object();s.watch(i);var w=s.beginNativeSelectedSetter(i,2);IssuedReturnMutationJournal.mutation(i);IssuedReturnMutationJournal.selectedSlotMutation(i,2);assertFalse(s.finishNativeSelectedSetter(w,true));}finally{s.close();}}
 @Test void laterManualAbaCannotRearmSuccessfulWindow(){var s=IssuedReturnMutationJournal.open();try{var i=new Object();s.watch(i);var w=s.beginNativeSelectedSetter(i,2);IssuedReturnMutationJournal.selectedSlotMutation(i,2);assertTrue(s.finishNativeSelectedSetter(w,true));IssuedReturnMutationJournal.selectedSlotMutation(i,3);IssuedReturnMutationJournal.selectedSlotMutation(i,2);assertFalse(s.current());assertNull(s.beginNativeSelectedSetter(i,2));}finally{s.close();}}
 @Test void anotherSnapshotCannotFinishOriginalToken(){var a=IssuedReturnMutationJournal.open();var b=IssuedReturnMutationJournal.open();try{var i=new Object();a.watch(i);b.watch(i);var w=a.beginNativeSelectedSetter(i,2);assertFalse(b.finishNativeSelectedSetter(w,true));IssuedReturnMutationJournal.selectedSlotMutation(i,2);assertTrue(a.finishNativeSelectedSetter(w,true));assertFalse(b.current());}finally{a.close();b.close();}}
 @Test void windowCannotBeFinishedOrReusedTwice(){var s=IssuedReturnMutationJournal.open();try{var i=new Object();s.watch(i);var w=s.beginNativeSelectedSetter(i,2);IssuedReturnMutationJournal.selectedSlotMutation(i,2);assertTrue(s.finishNativeSelectedSetter(w,true));assertFalse(s.finishNativeSelectedSetter(w,true));assertFalse(s.current());}finally{s.close();}}
 @Test void closingScopeCannotLeaveAUsableWindow(){var s=IssuedReturnMutationJournal.open();var i=new Object();s.watch(i);var w=s.beginNativeSelectedSetter(i,2);s.close();IssuedReturnMutationJournal.selectedSlotMutation(i,2);assertFalse(s.finishNativeSelectedSetter(w,true));}
 @Test void foreignThreadNativeSetterCannotConsumeWindow() throws Exception {var s=IssuedReturnMutationJournal.open();try{var i=new Object();s.watch(i);var w=s.beginNativeSelectedSetter(i,2);var t=new Thread(()->IssuedReturnMutationJournal.selectedSlotMutation(i,2));t.start();t.join();assertFalse(s.finishNativeSelectedSetter(w,true));}finally{s.close();}}
}
